21	// MAIN //
22	
23	/**
24	* Tests if two double-precision floating-point numbers are the same value.
25	*
26	* ## Notes
27	*
28	* -   The function implements the [SameValue Algorithm][ecma-262-same-value-algorithm], as specified in ECMAScript 5.
29	* -   In contrast to the strict equality operator `===`, `-0` and `+0` are distinguishable and `NaNs` are the same.
30	*
31	* [ecma-262-same-value-algorithm]: http://ecma-international.org/ecma-262/5.1/#sec-9.12
32	*
33	* @param {number} a - first input value
34	* @param {number} b - second input value
35	* @returns {boolean} boolean indicating whether two double-precision floating-point numbers are the same value
36	*
37	* @example
38	* var bool = isSameValue( 3.14, 3.14 );
39	* // returns true
40	*
41	* @example
42	* var bool = isSameValue( -0.0, -0.0 );
43	* // returns true
44	*
45	* @example
46	* var bool = isSameValue( -0.0, 0.0 );
47	* // returns false
48	*
49	* @example
50	* var bool = isSameValue( NaN, NaN );
51	* // returns true
52	*/
53	function isSameValue( a, b ) {
54		if ( a === b ) {
55			if ( a === 0.0 ) {
56				return 1.0 / a === 1.0 / b; // handles +-0
57			}
58			return true;
59		}
60		return ( a !== a && b !== b ); // handles NaNs
61	}
62	
63	
64	// EXPORTS //
65	
66	module.exports = isSameValue;
